import {
  Api2
} from "./fetch-jxc39wgw.js";

// src/handlers/project.ts
import { Project } from "@opencode/core/project";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/unstable/httpapi";
import { ProjectNotFoundError } from "@opencode/protocol/errors";
var ProjectHandler2 = HttpApiBuilder.group(Api2, "server.project", (handlers) => handlers.handle("project.list", () => Project.Service.use((project) => project.list())).handle("project.update", (ctx) => Project.Service.use((project) => project.update({ ...ctx.payload, projectID: ctx.params.projectID }).pipe(Effect.mapError(() => new ProjectNotFoundError({
  projectID: ctx.params.projectID,
  message: `Project not found: ${ctx.params.projectID}`
}))))));

export { ProjectHandler2 };
